package com.hostel.hostelmanagement.entity; import com.hostel.hostelmanagement.enums.LeaveStatus; import jakarta.persistence.*; import java.time.LocalDate; @Entity @Table(name="leave_requests") public class LeaveRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne User student; LocalDate fromDate,toDate; String reason; @Enumerated(EnumType.STRING) LeaveStatus status=LeaveStatus.PENDING; public LeaveRequest(){} public Long getId(){return id;} public User getStudent(){return student;} public LocalDate getFromDate(){return fromDate;} public LocalDate getToDate(){return toDate;} public String getReason(){return reason;} public LeaveStatus getStatus(){return status;} public void setId(Long v){id=v;} public void setStudent(User v){student=v;} public void setFromDate(LocalDate v){fromDate=v;} public void setToDate(LocalDate v){toDate=v;} public void setReason(String v){reason=v;} public void setStatus(LeaveStatus v){status=v;} }